const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict');
const source=fs.readFileSync(__dirname+'/index.html','utf8');const match=source.match(/<script id="motion-core">([\s\S]*?)<\/script>/);assert.ok(match,'Motion core must exist');const context=vm.createContext({});vm.runInContext(match[1],context);const m=context.PhaseGarden;
const s=m.create(false);m.advance(s,1);assert.equal(s.time,1);m.toggle(s);m.advance(s,1);assert.equal(s.time,1);m.seek(s,12);assert.equal(s.time,12);assert.equal(s.playing,false);m.replay(s);assert.equal(s.time,0);assert.equal(s.playing,true);m.seek(s,90);assert.equal(s.time,30);m.seek(s,-1);assert.equal(s.time,0);const reduced=m.create(true);m.advance(reduced,1);assert.equal(reduced.time,0);m.toggle(reduced);m.advance(reduced,1);assert.equal(reduced.time,1);const p=m.point(.8,2,0,.8);assert.notDeepEqual(m.point(.8,2,12,.8),p);assert.notDeepEqual(m.point(.8,2,0,.2),p);for(let i=0;i<100;i++)assert.ok(m.point(i/10,i%28,i%30,1.6).every(Number.isFinite));console.log('PASS: playback, pause, seek, clamping, replay, reduced motion, time geometry, amplitude geometry, finite coordinates.');
